import sys

# Increase recursion depth just in case, though not needed for this iterative solution
sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        p = int(next(iterator))
    except StopIteration:
        return

    A = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(next(iterator)))
        A.append(row)

    # Count zeros in A to determine |Z|
    Z_count = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                Z_count += 1

    # Case p = 2
    if p == 2:
        # For p=2, B is always the all-ones matrix J.
        # B^p = J^2 = N * J (mod 2).
        # So the result is N % 2 for all entries.
        val = N % 2
        for i in range(N):
            print(" ".join([str(val)] * N))
        return

    # Case p > 2
    # We need to compute S = A^p (mod p)
    # Then add contributions from self-loops in Z
    # And if p=3, add contributions from specific paths

    # Matrix multiplication function
    def mat_mul(X, Y, mod):
        n = len(X)
        Z = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if X[i][k] == 0:
                    continue
                val = X[i][k]
                row_y = Y[k]
                row_z = Z[i]
                for j in range(n):
                    row_z[j] = (row_z[j] + val * row_y[j]) % mod
        return Z

    # Matrix exponentiation function
    def mat_pow(X, exp, mod):
        n = len(X)
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = 1
        base = X
        while exp > 0:
            if exp % 2 == 1:
                res = mat_mul(res, base, mod)
            base = mat_mul(base, base, mod)
            exp //= 2
        return res

    # Compute A^p
    S = mat_pow(A, p, p)

    # Add contributions from self-loops in Z
    # For each u such that A[u][u] == 0:
    # Add column u of A to column u of S
    # Add row u of A to row u of S
    for u in range(N):
        if A[u][u] == 0:
            # Add column u
            col_u = [A[i][u] for i in range(N)]
            for i in range(N):
                S[i][u] = (S[i][u] + col_u[i]) % p

            # Add row u
            row_u = A[u]
            for j in range(N):
                S[u][j] = (S[u][j] + row_u[j]) % p

    # If p = 3, add contributions from paths u -> v -> u -> v
    # where (u,v) in Z and (v,u) not in Z
    if p == 3:
        for u in range(N):
            for v in range(N):
                if u == v:
                    continue
                if A[u][v] == 0 and A[v][u] != 0:
                    # Add A[v][u] to S[u][v]
                    S[u][v] = (S[u][v] + A[v][u]) % p

    # Multiply by (-1)^|Z|
    if Z_count % 2 == 1:
        for i in range(N):
            for j in range(N):
                S[i][j] = (p - S[i][j]) % p

    # Print result
    for i in range(N):
        print(" ".join(map(str, S[i])))

if __name__ == '__main__':
    solve()
