from typing import List
import ast

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Dictionary to store values for each diagonal
        # Key: r - c, Value: list of values
        diagonals = {}

        # Collect values for each diagonal
        # We iterate row by row, so for a fixed k, values are collected in increasing order of r
        for r in range(n):
            for c in range(n):
                k = r - c
                if k not in diagonals:
                    diagonals[k] = []
                diagonals[k].append(grid[r][c])

        # Sort the diagonals based on the rules
        for k in diagonals:
            if k >= 0:
                # Bottom-left triangle (including middle diagonal): non-increasing
                diagonals[k].sort(reverse=True)
            else:
                # Top-right triangle: non-decreasing
                diagonals[k].sort()

        # Reconstruct the matrix
        # We need to keep track of the current index for each diagonal
        diag_idx = {k: 0 for k in diagonals}

        for r in range(n):
            for c in range(n):
                k = r - c
                grid[r][c] = diagonals[k][diag_idx[k]]
                diag_idx[k] += 1

        return grid

if __name__ == "__main__":
    # Read all input from stdin
    input_data = sys.stdin.read().strip()
    if input_data:
        try:
            # Parse the input string into a list of lists
            grid = ast.literal_eval(input_data)
            solution = Solution()
            result = solution.sortMatrix(grid)
            # Print the result
            print(result)
        except Exception:
            pass
