class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible starting positions for a substring of length k
        for i in range(n - k + 1):
            # Check if the substring s[i : i+k] consists of only one distinct character
            # We can check if all characters in the substring are equal to s[i]
            # Since k is small (<= 100), slicing and set is efficient enough.
            sub = s[i : i+k]
            if len(set(sub)) == 1:
                # Check the character immediately before the substring
                # If it exists, it must be different from the character in the substring
                if i > 0:
                    if s[i-1] == s[i]:
                        continue # Invalid: previous character is the same

                # Check the character immediately after the substring
                # If it exists, it must be different from the character in the substring
                if i + k < n:
                    if s[i+k] == s[i]:
                        continue # Invalid: next character is the same

                # If we passed all checks, we found a valid substring
                return True

        return False

