from typing import List
import ast

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counts = {}
        n = len(nums)
        # Iterate through all subarrays of size k
        # There are n - k + 1 such subarrays
        for i in range(n - k + 1):
            sub = nums[i : i+k]
            # Use a set to count unique occurrences in this subarray.
            # If an element appears multiple times in the same subarray,
            # it still counts as appearing in that subarray once.
            unique_elements = set(sub)
            for x in unique_elements:
                counts[x] = counts.get(x, 0) + 1

        # Find the largest integer that appears in exactly one subarray
        result = -1
        for x, count in counts.items():
            if count == 1:
                if x > result:
                    result = x
        return result

if __name__ == '__main__':
    try:
        # Read input from stdin
        # We expect two lines: first line is the list, second line is k
        lines = []
        while len(lines) < 2:
            try:
                line = input().strip()
                if line:
                    lines.append(line)
            except EOFError:
                break

        if len(lines) >= 2:
            nums = ast.literal_eval(lines[0])
            k = int(lines[1])
            sol = Solution()
            print(sol.largestInteger(nums, k))
