from collections import Counter

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count the frequency of each digit in the string
        counts = Counter(s)

        # Iterate through the string to find adjacent pairs
        for i in range(len(s) - 1):
            d1 = s[i]
            d2 = s[i+1]

            # Condition 1: Digits must be different
            if d1 == d2:
                continue

            # Condition 2: Count must match numeric value
            # d1 and d2 are characters, convert to int for comparison
            if counts[d1] == int(d1) and counts[d2] == int(d2):
                return s[i:i+2]

        return ""

