import sys

# Increase recursion depth just in case, though not needed for this iterative solution
sys.setrecursionlimit(2000)

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # Precompute binomial coefficients C[n][k]
        # Max n is L, max k is L
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

        # Compute sets S_0, S_1, ..., S_{k-1}
        # S_i is the set of integers c such that cnt^{(i)}(c) = 1
        # S_0 = {1}
        # S_i = {c in [1, L] | cnt(c) in S_{i-1}}

        S_prev = {1}
        for _ in range(k - 1):
            S_curr = set()
            for c in range(1, L + 1):
                # cnt(c) is the number of set bits in c
                cnt_c = bin(c).count('1')
                if cnt_c in S_prev:
                    S_curr.add(c)
            S_prev = S_curr

        # S_prev now contains S_{k-1}
        # We need to count x < n such that cnt(x) in S_{k-1}

        ans = 0

        # For each valid count c, count number of x < n with cnt(x) = c
        # This is done by iterating through the binary string s
        # and summing combinations for positions where we can place '0'

        for c in S_prev:
            count = 0
            ones = 0
            for i in range(L):
                if s[i] == '1':
                    # If we place '0' at this position, the number becomes strictly less than s
                    # We have 'ones' ones placed so far.
                    # We need to place (c - ones) ones in the remaining (L - 1 - i) positions.
                    rem = L - 1 - i
                    needed = c - ones
                    if 0 <= needed <= rem:
                        count = (count + C[rem][needed]) % MOD
                    # If we place '1', we continue to match s
                    ones += 1
                else:
                    # s[i] == '0', we must place '0' to stay less or equal
                    # We cannot place '1' because that would make it greater than s
                    pass

            ans = (ans + count) % MOD

        return ans

if __name__ == "__main__":
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        exit()

    s = input_data[0].strip('"')
    k = int(input_data[1])

    solution = Solution()
    result = solution.countKReducibleNumbers(s, k)
    print(result)
