import sys
from typing import List
import ast

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # If the minimum element in nums is less than k, it's impossible to make all elements equal to k
        # because operations only decrease values.
        if min(nums) < k:
            return -1

        # We need to reduce all elements greater than k to k.
        # An operation with a valid h reduces all elements > h to h.
        # To minimize operations, we should reduce the largest unique value > k to the second largest unique value > k,
        # or to k if there is only one unique value > k.
        # Each such operation reduces the count of unique values > k by 1.
        # Thus, the minimum number of operations is the number of unique values strictly greater than k.

        unique_greater = set()
        for x in nums:
            if x > k:
                unique_greater.add(x)

        return len(unique_greater)

if __name__ == "__main__":
    # Read all input from stdin
    input_data = sys.stdin.read()
    if not input_data:
        sys.exit(0)

    # Find the list part
    start_idx = input_data.find('[')
    end_idx = input_data.rfind(']')

    if start_idx != -1 and end_idx != -1 and end_idx > start_idx:
        nums_str = input_data[start_idx : end_idx + 1]
        try:
            nums = ast.literal_eval(nums_str)
        except Exception:
            # Fallback if parsing fails
            sys.exit(1)

        # Parse k from the rest
        rest = input_data[end_idx + 1:]
        tokens = rest.split()
        if tokens:
            try:
                k = int(tokens[0])
            except Exception:
                sys.exit(1)
        else:
            # Fallback if k is not found
            sys.exit(1)
    else:
        # Fallback to line-based parsing if brackets are not found (unlikely based on problem description)
        lines = input_data.strip().split('\n')
        lines = [line.strip() for line in lines if line.strip()]
        if len(lines) >= 2:
            try:
                nums = ast.literal_eval(lines[0])
                k = int(lines[1])
            except Exception:
                sys.exit(1)
        else:
            sys.exit(1)

    sol = Solution()
    result = sol.minOperations(nums, k)
    print(result)
